// spec: specs/search-filters.md (1.5) · кейс: .qa/tests/search-filters/FILTER-PRICE-05.md
// seed: tests/seed.spec.ts (гость) · прод, только чтение. На карте только объявления с координатами,
// поэтому эталон числа — та же карта, открытая сразу с ?minPrice=&maxPrice=.
import { test, expect } from '@playwright/test';
import { prepareReadOnly, openPage, openFilter, fields, enter, applyFilter, foundCount, EnterMode, LOAD } from './search-filters.helpers';

test.use({ serviceWorkers: 'block' });

const MIN = 1_000_000;
const MAX = 3_000_000;
const VARIANTS: { mode: EnterMode; order: 'мин→макс' | 'макс→мин' }[] = [
  { mode: 'type', order: 'мин→макс' },
  { mode: 'type', order: 'макс→мин' },
  { mode: 'fill', order: 'мин→макс' },
];

test.describe('Фильтры поиска — поля мин/макс, десктоп /mapview', () => {
  for (const v of VARIANTS) {
    test(`/mapview: поля (${v.mode === 'type' ? 'по цифре' : 'вставкой'}, ${v.order}) — значения сохраняются, «נמצאו N» = карта с тем же диапазоном #b4b8c9 @desktop @prod-safe`, async ({ page, context }) => {
      await prepareReadOnly(context);
      await openPage(page, `/mapview?minPrice=${MIN}&maxPrice=${MAX}`);
      const reference = await foundCount(page);
      await openPage(page, '/mapview');
      const unfiltered = await foundCount(page);
      expect(reference, 'диапазон на карте сужает выдачу — иначе данные сайта').toBeLessThan(unfiltered);

      const scope = await openFilter(page, false);
      const f = fields(scope);
      const seq = v.order === 'мин→макс' ? [[f.min, MIN], [f.max, MAX]] as const : [[f.max, MAX], [f.min, MIN]] as const;
      await enter(seq[0][0], seq[0][1], v.mode);
      await enter(seq[1][0], seq[1][1], v.mode);
      await expect(f.min, 'после ввода второго поля первое не стёрлось').toHaveValue(String(MIN));

      await applyFilter(page);
      await expect.poll(() => foundCount(page), { message: '«נמצאו N» = карта с ?minPrice&maxPrice', ...LOAD }).toBe(reference);
      await expect(f.min, 'после «סנן תוצאות» мин на месте').toHaveValue(String(MIN));
      await expect(f.max, 'после «סנן תוצאות» макс на месте').toHaveValue(String(MAX));
    });
  }
});
